svg.script:
(function(){
  var svg = document.documentElement;
  var popup = document.getElementById('popup');
  var ptext = document.getElementById('popupText');
  var prect = document.getElementById('popupRect');
  var W = 1000, H = 500;
  // 静态地图：无缩放、无平移、无拖动
  function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
  function showPopup(en, x, y){
    ptext.textContent = en;
    var tw = Math.max(48, en.length * 8.0 + 22);
    prect.setAttribute('width', tw);
    prect.setAttribute('x', -tw/2);
    var bx = clamp(x, tw/2 + 4, W - tw/2 - 4);
    var by = clamp(y, 34, H - 4);
    popup.setAttribute('transform','translate('+bx.toFixed(2)+' '+by.toFixed(2)+')');
    popup.style.display = 'block';
  }
  function hidePopup(){ popup.style.display = 'none'; }
  var markers = document.querySelectorAll('.marker');
  markers.forEach(function(m){
    m.addEventListener('mouseenter', function(){
      showPopup(m.getAttribute('data-en'), parseFloat(m.getAttribute('data-x')), parseFloat(m.getAttribute('data-y')));
    });
    m.addEventListener('mouseleave', hidePopup);
  });
})();
